#[derive(Debug, Clone, Copy)]
pub struct Token {
    pub kind: TokenKind,
    span: Span,
}
impl Token {
    pub fn as_parse_tree<'a>(&self) -> ParseTree<'a> {
        ParseTree::Token(*self)
    }
    pub fn span(&self) -> Span {
        self.span
    }
}
fn token_kind(terminal_id: TerminalId) -> TokenKind {
    match terminal_id {
        // WhiteSpace
        TerminalId(0) => TokenKind::T0,
        // Name
        TerminalId(1) => TokenKind::T1,
        // ","
        TerminalId(2) => TokenKind::T2,
        // "names"
        TerminalId(3) => TokenKind::T3,
        // "if"
        TerminalId(4) => TokenKind::T4,
        // "else"
        TerminalId(5) => TokenKind::T5,
        // "single"
        TerminalId(6) => TokenKind::T6,
        // "written"
        TerminalId(7) => TokenKind::T7,
        // "mixed"
        TerminalId(8) => TokenKind::T8,
        // "expect"
        TerminalId(9) => TokenKind::T9,
        // ";"
        TerminalId(10) => TokenKind::T10,
        // "k"
        TerminalId(11) => TokenKind::T11,
        // "v"
        TerminalId(12) => TokenKind::T12,
        // "w"
        TerminalId(13) => TokenKind::T13,
        _ => unreachable!("Unknown TerminalId: {:?}", terminal_id),
    }
}
pub struct SequenceOperandsParseTreeBuilder<'a> {
    pub arena: &'a Arena,
}
impl<'a> SequenceOperandsParseTreeBuilder<'a> {
    pub fn new(tree_arena: &'a Arena) -> Self {
        Self { arena: tree_arena }
    }
    fn ambiguity_node(
        &self,
        parent: NonterminalId,
        alternatives: &'a [ParseTree<'a>],
    ) -> ParseTree<'a> {
        match parent {
            grammar::ITEMS => ParseTree::Items(self.arena.alloc(Items::Amb(alternatives))),
            grammar::NAMES => ParseTree::Names(self.arena.alloc(Names::Amb(alternatives))),
            grammar::SEPARATED => {
                ParseTree::Separated(self.arena.alloc(Separated::Amb(alternatives)))
            }
            grammar::PAIRS => ParseTree::Pairs(self.arena.alloc(Pairs::Amb(alternatives))),
            grammar::ELSE => ParseTree::Else(self.arena.alloc(Else::Amb(alternatives))),
            grammar::SINGLE => ParseTree::Single(self.arena.alloc(Single::Amb(alternatives))),
            grammar::WRITTEN => ParseTree::Written(self.arena.alloc(Written::Amb(alternatives))),
            grammar::MIXED => ParseTree::Mixed(self.arena.alloc(Mixed::Amb(alternatives))),
            grammar::EXPECTED => ParseTree::Expected(self.arena.alloc(Expected::Amb(alternatives))),
            grammar::ITEM => ParseTree::Item(self.arena.alloc(Item::Amb(alternatives))),
            grammar::KEY => ParseTree::Key(self.arena.alloc(Key::Amb(alternatives))),
            grammar::VALUE => ParseTree::Value(self.arena.alloc(Value::Amb(alternatives))),
            grammar::CHOICE => ParseTree::Choice(self.arena.alloc(Choice::Amb(alternatives))),
            grammar::LAYOUT => ParseTree::Layout(self.arena.alloc(Layout::Amb(alternatives))),
            grammar::PLUS_0 => ParseTree::Plus0(self.arena.alloc(Plus0::Amb(alternatives))),
            grammar::STAR_0 => ParseTree::Star0(self.arena.alloc(Star0::Amb(alternatives))),
            grammar::PLUS_1 => ParseTree::Plus1(self.arena.alloc(Plus1::Amb(alternatives))),
            grammar::STAR_1 => ParseTree::Star1(self.arena.alloc(Star1::Amb(alternatives))),
            grammar::PLUS_2 => ParseTree::Plus2(self.arena.alloc(Plus2::Amb(alternatives))),
            grammar::OPT_0 => ParseTree::Opt0(self.arena.alloc(Opt0::Amb(alternatives))),
            grammar::OPT_1 => ParseTree::Opt1(self.arena.alloc(Opt1::Amb(alternatives))),
            grammar::GROUP_0 => ParseTree::Group0(self.arena.alloc(Group0::Amb(alternatives))),
            grammar::PLUS_3 => ParseTree::Plus3(self.arena.alloc(Plus3::Amb(alternatives))),
            grammar::STAR_2 => ParseTree::Star2(self.arena.alloc(Star2::Amb(alternatives))),
            grammar::OPT_2 => ParseTree::Opt2(self.arena.alloc(Opt2::Amb(alternatives))),
            grammar::PLUS_4 => ParseTree::Plus4(self.arena.alloc(Plus4::Amb(alternatives))),
            grammar::PLUS_5 => ParseTree::Plus5(self.arena.alloc(Plus5::Amb(alternatives))),
            grammar::OPT_3 => ParseTree::Opt3(self.arena.alloc(Opt3::Amb(alternatives))),
            grammar::START_ITEMS => self.start_ambiguity_node(grammar::ITEMS, alternatives),
            grammar::START_NAMES => self.start_ambiguity_node(grammar::NAMES, alternatives),
            grammar::START_SEPARATED => self.start_ambiguity_node(grammar::SEPARATED, alternatives),
            grammar::START_PAIRS => self.start_ambiguity_node(grammar::PAIRS, alternatives),
            grammar::START_ELSE => self.start_ambiguity_node(grammar::ELSE, alternatives),
            grammar::START_SINGLE => self.start_ambiguity_node(grammar::SINGLE, alternatives),
            grammar::START_WRITTEN => self.start_ambiguity_node(grammar::WRITTEN, alternatives),
            grammar::START_MIXED => self.start_ambiguity_node(grammar::MIXED, alternatives),
            grammar::START_EXPECTED => self.start_ambiguity_node(grammar::EXPECTED, alternatives),
            grammar::START_ITEM => self.start_ambiguity_node(grammar::ITEM, alternatives),
            grammar::START_KEY => self.start_ambiguity_node(grammar::KEY, alternatives),
            grammar::START_VALUE => self.start_ambiguity_node(grammar::VALUE, alternatives),
            grammar::START_CHOICE => self.start_ambiguity_node(grammar::CHOICE, alternatives),
            grammar::START_LAYOUT => self.start_ambiguity_node(grammar::LAYOUT, alternatives),
            _ => unreachable!("nonterminal cannot be ambiguous"),
        }
    }
    fn start_ambiguity_node(
        &self,
        inner: NonterminalId,
        alternatives: &'a [ParseTree<'a>],
    ) -> ParseTree<'a> {
        let first = alternatives[0].unwrap_start();
        let inner_alternatives = self
            .arena
            .alloc_slice(alternatives.iter().map(|a| a.unwrap_start().node));
        ParseTree::Start(self.arena.alloc(Start {
            before: first.before,
            node: self.ambiguity_node(inner, inner_alternatives),
            after: first.after,
            span: first.span,
        }))
    }
}
impl<'a> ParseTreeBuilder<ParseTree<'a>> for SequenceOperandsParseTreeBuilder<'a> {
    fn new_nonterminal_node(
        &self,
        nonterminal_node: &NonterminalNode,
        children: &[ParseTree<'a>],
    ) -> ParseTree<'a> {
        match nonterminal_node.return_slot {
            // Items = Item Layout ("," Item)*
            SlotId(3) => {
                let &[item, layout, star_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Items(self.arena.alloc(Items::Alt0 {
                    item: item.unwrap_item(),
                    layout: layout.unwrap_layout(),
                    star_0: star_0.unwrap_star_0(),
                    span: nonterminal_node.span,
                }))
            }
            // Names = "names" Layout ("," Name)*
            SlotId(7) => {
                let &[lit_0, layout, star_1] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Names(self.arena.alloc(Names::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    layout: layout.unwrap_layout(),
                    star_1: star_1.unwrap_star_1(),
                    span: nonterminal_node.span,
                }))
            }
            // Separated = ("," Item)+
            SlotId(9) => {
                let &[plus_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Separated(self.arena.alloc(Separated::Alt0 {
                    plus_0: plus_0.unwrap_plus_0(),
                    span: nonterminal_node.span,
                }))
            }
            // Pairs = (Key Value)+
            SlotId(11) => {
                let &[plus_2] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Pairs(self.arena.alloc(Pairs::Alt0 {
                    plus_2: plus_2.unwrap_plus_2(),
                    span: nonterminal_node.span,
                }))
            }
            // Else = "if" Layout Item Layout ("else" Item)?
            SlotId(17) => {
                let &[lit_0, layout_1, item, layout_3, opt_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Else(self.arena.alloc(Else::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    layout_1: layout_1.unwrap_layout(),
                    item: item.unwrap_item(),
                    layout_3: layout_3.unwrap_layout(),
                    opt_0: opt_0.unwrap_opt_0(),
                    span: nonterminal_node.span,
                }))
            }
            // Single = "single" Layout (Item)?
            SlotId(21) => {
                let &[lit_0, layout, opt_1] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Single(self.arena.alloc(Single::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    layout: layout.unwrap_layout(),
                    opt_1: opt_1.unwrap_opt_1(),
                    span: nonterminal_node.span,
                }))
            }
            // Written = "written" Layout ((Key Value))*
            SlotId(25) => {
                let &[lit_0, layout, star_2] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Written(self.arena.alloc(Written::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    layout: layout.unwrap_layout(),
                    star_2: star_2.unwrap_star_2(),
                    span: nonterminal_node.span,
                }))
            }
            // Mixed = "mixed" Layout (Key (Value Value)?)+
            SlotId(29) => {
                let &[lit_0, layout, plus_4] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Mixed(self.arena.alloc(Mixed::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    layout: layout.unwrap_layout(),
                    plus_4: plus_4.unwrap_plus_4(),
                    span: nonterminal_node.span,
                }))
            }
            // Expected = "expect" Layout (Key Choice)+ Layout ";"
            SlotId(35) => {
                let &[lit_0, layout_1, plus_5, layout_3, lit_4] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Expected(self.arena.alloc(Expected::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    layout_1: layout_1.unwrap_layout(),
                    plus_5: plus_5.unwrap_plus_5(),
                    layout_3: layout_3.unwrap_layout(),
                    lit_4: lit_4.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // Item = Name
            SlotId(37) => {
                let &[name] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Item(self.arena.alloc(Item::Alt0 {
                    name: name.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // Key = "k"
            SlotId(39) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Key(self.arena.alloc(Key::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // Value = "v"
            SlotId(41) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Value(self.arena.alloc(Value::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // Choice = "v"
            SlotId(43) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Choice(self.arena.alloc(Choice::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // Choice = "w"
            SlotId(45) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Choice(self.arena.alloc(Choice::Alt1 {
                    lit_0: lit_0.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // Layout = WhiteSpace?
            SlotId(47) => {
                let &[white_space] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Layout(self.arena.alloc(Layout::Alt0 {
                    white_space: white_space.unwrap_opt_3(),
                    span: nonterminal_node.span,
                }))
            }
            // Plus_0 = ("," Item)+ Layout "," Layout Item
            SlotId(53) => {
                let &[plus_0, layout_1, lit_2, layout_3, item] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus0(self.arena.alloc(Plus0::Alt0 {
                    plus_0: plus_0.unwrap_plus_0(),
                    layout_1: layout_1.unwrap_layout(),
                    lit_2: lit_2.unwrap_token(),
                    layout_3: layout_3.unwrap_layout(),
                    item: item.unwrap_item(),
                    span: nonterminal_node.span,
                }))
            }
            // Plus_0 = "," Layout Item
            SlotId(57) => {
                let &[lit_0, layout, item] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus0(self.arena.alloc(Plus0::Alt1 {
                    lit_0: lit_0.unwrap_token(),
                    layout: layout.unwrap_layout(),
                    item: item.unwrap_item(),
                    span: nonterminal_node.span,
                }))
            }
            // Star_0 = ("," Item)+
            SlotId(59) => {
                let &[plus_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Star0(self.arena.alloc(Star0::Alt0 {
                    plus_0: plus_0.unwrap_plus_0(),
                    span: nonterminal_node.span,
                }))
            }
            // Star_0 =
            SlotId(60) => {
                let &[] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Star0(self.arena.alloc(Star0::Alt1 {
                    span: nonterminal_node.span,
                }))
            }
            // Plus_1 = ("," Name)+ Layout "," Layout Name
            SlotId(66) => {
                let &[plus_1, layout_1, lit_2, layout_3, name] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus1(self.arena.alloc(Plus1::Alt0 {
                    plus_1: plus_1.unwrap_plus_1(),
                    layout_1: layout_1.unwrap_layout(),
                    lit_2: lit_2.unwrap_token(),
                    layout_3: layout_3.unwrap_layout(),
                    name: name.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // Plus_1 = "," Layout Name
            SlotId(70) => {
                let &[lit_0, layout, name] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus1(self.arena.alloc(Plus1::Alt1 {
                    lit_0: lit_0.unwrap_token(),
                    layout: layout.unwrap_layout(),
                    name: name.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // Star_1 = ("," Name)+
            SlotId(72) => {
                let &[plus_1] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Star1(self.arena.alloc(Star1::Alt0 {
                    plus_1: plus_1.unwrap_plus_1(),
                    span: nonterminal_node.span,
                }))
            }
            // Star_1 =
            SlotId(73) => {
                let &[] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Star1(self.arena.alloc(Star1::Alt1 {
                    span: nonterminal_node.span,
                }))
            }
            // Plus_2 = (Key Value)+ Layout Key Layout Value
            SlotId(79) => {
                let &[plus_2, layout_1, key, layout_3, value] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus2(self.arena.alloc(Plus2::Alt0 {
                    plus_2: plus_2.unwrap_plus_2(),
                    layout_1: layout_1.unwrap_layout(),
                    key: key.unwrap_key(),
                    layout_3: layout_3.unwrap_layout(),
                    value: value.unwrap_value(),
                    span: nonterminal_node.span,
                }))
            }
            // Plus_2 = Key Layout Value
            SlotId(83) => {
                let &[key, layout, value] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus2(self.arena.alloc(Plus2::Alt1 {
                    key: key.unwrap_key(),
                    layout: layout.unwrap_layout(),
                    value: value.unwrap_value(),
                    span: nonterminal_node.span,
                }))
            }
            // Opt_0 = "else" Layout Item
            SlotId(87) => {
                let &[lit_0, layout, item] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Opt0(self.arena.alloc(Opt0::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    layout: layout.unwrap_layout(),
                    item: item.unwrap_item(),
                    span: nonterminal_node.span,
                }))
            }
            // Opt_0 =
            SlotId(88) => {
                let &[] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Opt0(self.arena.alloc(Opt0::Alt1 {
                    span: nonterminal_node.span,
                }))
            }
            // Opt_1 = Item
            SlotId(90) => {
                let &[item] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Opt1(self.arena.alloc(Opt1::Alt0 {
                    item: item.unwrap_item(),
                    span: nonterminal_node.span,
                }))
            }
            // Opt_1 =
            SlotId(91) => {
                let &[] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Opt1(self.arena.alloc(Opt1::Alt1 {
                    span: nonterminal_node.span,
                }))
            }
            // Group_0 = Key Layout Value
            SlotId(95) => {
                let &[key, layout, value] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Group0(self.arena.alloc(Group0::Alt0 {
                    key: key.unwrap_key(),
                    layout: layout.unwrap_layout(),
                    value: value.unwrap_value(),
                    span: nonterminal_node.span,
                }))
            }
            // Plus_3 = ((Key Value))+ Layout (Key Value)
            SlotId(99) => {
                let &[plus_3, layout, group_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus3(self.arena.alloc(Plus3::Alt0 {
                    plus_3: plus_3.unwrap_plus_3(),
                    layout: layout.unwrap_layout(),
                    group_0: group_0.unwrap_group_0(),
                    span: nonterminal_node.span,
                }))
            }
            // Plus_3 = (Key Value)
            SlotId(101) => {
                let &[group_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus3(self.arena.alloc(Plus3::Alt1 {
                    group_0: group_0.unwrap_group_0(),
                    span: nonterminal_node.span,
                }))
            }
            // Star_2 = ((Key Value))+
            SlotId(103) => {
                let &[plus_3] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Star2(self.arena.alloc(Star2::Alt0 {
                    plus_3: plus_3.unwrap_plus_3(),
                    span: nonterminal_node.span,
                }))
            }
            // Star_2 =
            SlotId(104) => {
                let &[] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Star2(self.arena.alloc(Star2::Alt1 {
                    span: nonterminal_node.span,
                }))
            }
            // Opt_2 = Value Layout Value
            SlotId(108) => {
                let &[value_0, layout, value_2] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Opt2(self.arena.alloc(Opt2::Alt0 {
                    value_0: value_0.unwrap_value(),
                    layout: layout.unwrap_layout(),
                    value_2: value_2.unwrap_value(),
                    span: nonterminal_node.span,
                }))
            }
            // Opt_2 =
            SlotId(109) => {
                let &[] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Opt2(self.arena.alloc(Opt2::Alt1 {
                    span: nonterminal_node.span,
                }))
            }
            // Plus_4 = (Key (Value Value)?)+ Layout Key Layout (Value Value)?
            SlotId(115) => {
                let &[plus_4, layout_1, key, layout_3, opt_2] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus4(self.arena.alloc(Plus4::Alt0 {
                    plus_4: plus_4.unwrap_plus_4(),
                    layout_1: layout_1.unwrap_layout(),
                    key: key.unwrap_key(),
                    layout_3: layout_3.unwrap_layout(),
                    opt_2: opt_2.unwrap_opt_2(),
                    span: nonterminal_node.span,
                }))
            }
            // Plus_4 = Key Layout (Value Value)?
            SlotId(119) => {
                let &[key, layout, opt_2] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus4(self.arena.alloc(Plus4::Alt1 {
                    key: key.unwrap_key(),
                    layout: layout.unwrap_layout(),
                    opt_2: opt_2.unwrap_opt_2(),
                    span: nonterminal_node.span,
                }))
            }
            // Plus_5 = (Key Choice)+ Layout Key Layout Choice
            SlotId(125) => {
                let &[plus_5, layout_1, key, layout_3, choice] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus5(self.arena.alloc(Plus5::Alt0 {
                    plus_5: plus_5.unwrap_plus_5(),
                    layout_1: layout_1.unwrap_layout(),
                    key: key.unwrap_key(),
                    layout_3: layout_3.unwrap_layout(),
                    choice: choice.unwrap_choice(),
                    span: nonterminal_node.span,
                }))
            }
            // Plus_5 = Key Layout Choice
            SlotId(129) => {
                let &[key, layout, choice] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus5(self.arena.alloc(Plus5::Alt1 {
                    key: key.unwrap_key(),
                    layout: layout.unwrap_layout(),
                    choice: choice.unwrap_choice(),
                    span: nonterminal_node.span,
                }))
            }
            // Opt_3 = WhiteSpace
            SlotId(131) => {
                let &[white_space] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Opt3(self.arena.alloc(Opt3::Alt0 {
                    white_space: white_space.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // Opt_3 =
            SlotId(132) => {
                let &[] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Opt3(self.arena.alloc(Opt3::Alt1 {
                    span: nonterminal_node.span,
                }))
            }
            // The start nonterminals with layout
            SlotId(136) | SlotId(140) | SlotId(144) | SlotId(148) | SlotId(152) | SlotId(156)
            | SlotId(160) | SlotId(164) | SlotId(168) | SlotId(172) | SlotId(176) | SlotId(180)
            | SlotId(184) => {
                let &[before, node, after] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Start(self.arena.alloc(Start {
                    before: Some(before),
                    node,
                    after: Some(after),
                    span: nonterminal_node.span,
                }))
            }
            // The start nonterminals without layout
            SlotId(186) => {
                let &[node] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Start(self.arena.alloc(Start {
                    before: None,
                    node,
                    after: None,
                    span: nonterminal_node.span,
                }))
            }
            _ => unreachable!(),
        }
    }
    fn new_token(&self, terminal_node: &TerminalNode) -> ParseTree<'a> {
        ParseTree::Token(Token {
            kind: token_kind(terminal_node.terminal_id),
            span: terminal_node.span,
        })
    }
    fn new_ambiguity_node(
        &self,
        parent: NonterminalId,
        alternatives: Vec<ParseTree<'a>>,
    ) -> ParseTree<'a> {
        self.ambiguity_node(parent, self.arena.alloc_slice(alternatives))
    }
}
// The parse tree of a finished parse, from the nonterminal node that spans the input.
pub fn create_parse_tree<'a>(
    root_id: SPPFNodeId,
    parser: &SequenceOperandsParser,
    builder: &SequenceOperandsParseTreeBuilder<'a>,
) -> ParseTree<'a> {
    let iguana_runtime::sppf::SPPFNode::Nonterminal(root) =
        iguana_runtime::parser::Parser::sppf_node(parser, root_id)
    else {
        panic!("the SPPF root is not a nonterminal node")
    };
    match root.nonterminal_id {
        grammar::ITEMS => ParseTree::Items(visit_sppf(root_id, parser, builder).unwrap_items()),
        grammar::NAMES => ParseTree::Names(visit_sppf(root_id, parser, builder).unwrap_names()),
        grammar::SEPARATED => {
            ParseTree::Separated(visit_sppf(root_id, parser, builder).unwrap_separated())
        }
        grammar::PAIRS => ParseTree::Pairs(visit_sppf(root_id, parser, builder).unwrap_pairs()),
        grammar::ELSE => ParseTree::Else(visit_sppf(root_id, parser, builder).unwrap_else()),
        grammar::SINGLE => ParseTree::Single(visit_sppf(root_id, parser, builder).unwrap_single()),
        grammar::WRITTEN => {
            ParseTree::Written(visit_sppf(root_id, parser, builder).unwrap_written())
        }
        grammar::MIXED => ParseTree::Mixed(visit_sppf(root_id, parser, builder).unwrap_mixed()),
        grammar::EXPECTED => {
            ParseTree::Expected(visit_sppf(root_id, parser, builder).unwrap_expected())
        }
        grammar::ITEM => ParseTree::Item(visit_sppf(root_id, parser, builder).unwrap_item()),
        grammar::KEY => ParseTree::Key(visit_sppf(root_id, parser, builder).unwrap_key()),
        grammar::VALUE => ParseTree::Value(visit_sppf(root_id, parser, builder).unwrap_value()),
        grammar::CHOICE => ParseTree::Choice(visit_sppf(root_id, parser, builder).unwrap_choice()),
        grammar::LAYOUT => ParseTree::Layout(visit_sppf(root_id, parser, builder).unwrap_layout()),
        grammar::PLUS_0 => ParseTree::Plus0(visit_sppf(root_id, parser, builder).unwrap_plus_0()),
        grammar::STAR_0 => ParseTree::Star0(visit_sppf(root_id, parser, builder).unwrap_star_0()),
        grammar::PLUS_1 => ParseTree::Plus1(visit_sppf(root_id, parser, builder).unwrap_plus_1()),
        grammar::STAR_1 => ParseTree::Star1(visit_sppf(root_id, parser, builder).unwrap_star_1()),
        grammar::PLUS_2 => ParseTree::Plus2(visit_sppf(root_id, parser, builder).unwrap_plus_2()),
        grammar::OPT_0 => ParseTree::Opt0(visit_sppf(root_id, parser, builder).unwrap_opt_0()),
        grammar::OPT_1 => ParseTree::Opt1(visit_sppf(root_id, parser, builder).unwrap_opt_1()),
        grammar::GROUP_0 => {
            ParseTree::Group0(visit_sppf(root_id, parser, builder).unwrap_group_0())
        }
        grammar::PLUS_3 => ParseTree::Plus3(visit_sppf(root_id, parser, builder).unwrap_plus_3()),
        grammar::STAR_2 => ParseTree::Star2(visit_sppf(root_id, parser, builder).unwrap_star_2()),
        grammar::OPT_2 => ParseTree::Opt2(visit_sppf(root_id, parser, builder).unwrap_opt_2()),
        grammar::PLUS_4 => ParseTree::Plus4(visit_sppf(root_id, parser, builder).unwrap_plus_4()),
        grammar::PLUS_5 => ParseTree::Plus5(visit_sppf(root_id, parser, builder).unwrap_plus_5()),
        grammar::OPT_3 => ParseTree::Opt3(visit_sppf(root_id, parser, builder).unwrap_opt_3()),
        grammar::START_ITEMS
        | grammar::START_NAMES
        | grammar::START_SEPARATED
        | grammar::START_PAIRS
        | grammar::START_ELSE
        | grammar::START_SINGLE
        | grammar::START_WRITTEN
        | grammar::START_MIXED
        | grammar::START_EXPECTED
        | grammar::START_ITEM
        | grammar::START_KEY
        | grammar::START_VALUE
        | grammar::START_CHOICE
        | grammar::START_LAYOUT => {
            ParseTree::Start(visit_sppf(root_id, parser, builder).unwrap_start())
        }
        _ => panic!(),
    }
}
impl<'a> ParseTreeNode for ParseTree<'a> {
    fn child(&self, index: usize) -> Option<Self> {
        ParseTree::child(self, index)
    }
    fn child_count(&self) -> usize {
        ParseTree::child_count(self)
    }
    fn display_name(&self) -> &'static str {
        ParseTree::display_name(self)
    }
    fn span(&self) -> Span {
        ParseTree::span(self)
    }
    fn kind(&self) -> NodeKind {
        if self.is_amb() {
            NodeKind::Amb
        } else if matches!(self, ParseTree::Token(_)) {
            NodeKind::Token
        } else {
            NodeKind::Nonterminal
        }
    }
    fn node_id(&self) -> Option<usize> {
        ParseTree::node_id(self)
    }
    fn nonterminal_id(&self) -> Option<NonterminalId> {
        ParseTree::nonterminal_id(self)
    }
    fn origin(&self) -> Option<Origin> {
        ParseTree::origin(self)
    }
}
